async function captureCrossTabLayout(page,width,height,label){
  await page.setViewportSize({width,height});
  const targets={knowledge:'.knowledge-period-row',meeting:'#meeting-form>.grid','meeting-past':'.meeting-past-filter-grid','entity-workspace':'.entity-workspace-selector-grid','activity-analytics':'.analytics-controls',masters:'.master-layout','ai-provider-settings':'#admin-panel-provider .ai-provider-card .filter-grid'};
  const result={};
  for(const[name,selector]of Object.entries(targets)){
    await page.locator('#nav-'+name).click();
    const observation=await page.locator(selector).first().evaluate(node=>{
      const template=getComputedStyle(node).gridTemplateColumns,activePage=node.closest('.page');
      const brand=document.querySelector('.brand'),heading=brand.querySelector('h1'),visible=document.body.innerText;
      return {columns:template.split(' ').length,columnTemplate:template,
        overflowPx:Math.max(0,document.documentElement.scrollWidth-innerWidth),
        pageVisible:activePage.classList.contains('active'),pageNonblank:activePage.innerText.trim().length>0,
        brand:heading.textContent,brandChildren:brand.children.length,brandOverflow:heading.scrollWidth>heading.clientWidth+1,
        forbidden:(visible.match(/権威ある|authoritative|materializ|fail closed|stale source|provider response|\bEntity\b|\bRelationship\b|Knowledge Share|PRIVATE ASSETS KNOWLEDGE/ig)||[])};
    });
    const maxOverflow=name==='entity-workspace'&&width===390?176:0;
    assert.equal(observation.pageVisible,true,label+' '+name+' active');
    assert.equal(observation.pageNonblank,true,label+' '+name+' nonblank');
    assert.ok(observation.overflowPx<=maxOverflow,label+' '+name+' overflow '+observation.overflowPx+'px');
    assert.equal(observation.brand,'Private Assets Intelligence');
    assert.equal(observation.brandChildren,1);
    assert.equal(observation.brandOverflow,false,label+' '+name+' brand overflow');
    assert.deepEqual(observation.forbidden,[],label+' '+name+' forbidden copy');
    if(name!=='masters')assert.equal(observation.columns,width<=720?1:12,label+' '+name+' columns '+observation.columnTemplate);
    result[name]=observation;
    if(width===1440||width===390){await page.evaluate(()=>window.scrollTo(0,0));await page.screenshot({path:path.join(out,'work0053-page-'+name+'-'+width+'.png'),fullPage:false})}
  }
  return result;
}
